import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return [src]

    best_dist = {src: 0}
    best_path = {src: [src]}
    heap = [(0, [src], src)]

    while heap:
        dist, path, u = heapq.heappop(heap)

        if best_dist.get(u) != dist or best_path.get(u) != path:
            continue

        if u == dst:
            return path

        for v, w in graph.get(u, {}).items():
            nd = dist + w
            np = path + [v]

            if v not in best_dist or nd < best_dist[v] or (nd == best_dist[v] and np < best_path[v]):
                best_dist[v] = nd
                best_path[v] = np
                heapq.heappush(heap, (nd, np, v))

    return []
